/**
 * Typed access to the reference datasets generated by `pnpm grounding`:
 * Wikidata (src/data/wikidata), Statistics Canada (src/data/statcan) and the
 * flag credits (src/data/flags.json). Import from here rather than the JSON
 * files directly, so the shapes are checked in one place.
 */
import pmData from "../data/wikidata/prime-ministers.json";
import monarchData from "../data/wikidata/monarchs.json";
import ggData from "../data/wikidata/governors-general.json";
import cjData from "../data/wikidata/chief-justices.json";
import provinceData from "../data/wikidata/provinces.json";
import censusData from "../data/wikidata/population-history.json";
import flagData from "../data/flags.json";
import populationData from "../data/statcan/population.json";
import immigrationData from "../data/statcan/immigration.json";
import ageData from "../data/statcan/age.json";

// ---------------------------------------------------------------------------
// Shared shapes
// ---------------------------------------------------------------------------

export interface DatasetMeta {
  source: string;
  url: string;
  urls?: string[];
  licence: string;
  licenceUrl?: string;
  fetched: string;
  notes?: string[];
  query?: string;
  script?: string;
}

/** An ISO date (YYYY-MM-DD). `end: null` means still in office. */
export interface Term {
  start: string;
  end: string | null;
}

export interface Officeholder {
  ordinal: number;
  name: string;
  qid: string;
  wikipedia: string | null;
  terms: Term[];
}

export type PartyFamily = "lpc" | "cpc";

export interface PrimeMinisterTerm extends Term {
  parties: string[];
}

export interface PrimeMinister extends Omit<Officeholder, "terms"> {
  terms: PrimeMinisterTerm[];
  parties: string[];
}

export interface Province {
  slug: string;
  name: string;
  qid: string;
  type: "province" | "territory";
  capital: string;
  joined: string;
  areaKm2: number;
  population: number;
  populationDate: string;
  largestCity: { name: string; population: number; date: string };
  flagFile: string;
  premier: {
    name: string;
    qid: string;
    party: string | null;
    since: string | null;
    check: { wikidata: string | null; wikidataSince: string | null; agrees: boolean };
  } | null;
  wikipedia: string | null;
}

export interface Flag {
  slug: string;
  name: string;
  path: string;
  commonsFile: string;
  commonsUrl: string;
  licence: string;
  licenceUrl: string | null;
  author: string | null;
  credit: string | null;
  attributionRequired: boolean;
}

export interface Point {
  year: number;
  value: number;
}

export interface Geo {
  slug: string;
  name: string;
}

export interface ImmigrationYear {
  year: number;
  /** "1913" for calendar years, "1971/1972" for July–June years. */
  period: string;
  immigrants: number;
  per1000: number | null;
}

// ---------------------------------------------------------------------------
// Datasets
// ---------------------------------------------------------------------------

const meta = (d: { _meta: unknown }) => d._meta as DatasetMeta;

/** How each historical party maps onto the two colour families. See scripts/grounding/wikidata.ts. */
export const parties = pmData.parties as Record<string, { name: string; family: PartyFamily }>;
const familyByName = new Map(Object.values(parties).map((p) => [p.name, p.family]));

export const primeMinisters = pmData.primeMinisters as PrimeMinister[];
export const monarchs = monarchData.monarchs as Officeholder[];
export const governorsGeneral = ggData.governorsGeneral as Officeholder[];
export const chiefJustices = cjData.chiefJustices as Officeholder[];
export const provinces = provinceData.provinces as Province[];
export const censusHistory = censusData.census as Record<string, { year: number; population: number }[]>;
export const flags = flagData.flags as Flag[];

export const population = {
  geos: populationData.geos as Geo[],
  latestYear: populationData.latestYear as number,
  census: populationData.census as Record<string, Point[]>,
  estimates: populationData.estimates as Record<string, Point[]>,
};
export const immigration = immigrationData.canada as ImmigrationYear[];
export const age = {
  geos: ageData.geos as Geo[],
  medianAge: ageData.medianAge as Record<string, Point[]>,
  share0to14: ageData.share0to14 as Record<string, Point[]>,
  share65plus: ageData.share65plus as Record<string, Point[]>,
};

/** Every dataset with its provenance, for the credits page. */
export const datasets: { id: string; title: string; file: string; meta: DatasetMeta }[] = [
  { id: "prime-ministers", title: "Prime ministers", file: "src/data/wikidata/prime-ministers.json", meta: meta(pmData) },
  { id: "monarchs", title: "Monarchs", file: "src/data/wikidata/monarchs.json", meta: meta(monarchData) },
  { id: "governors-general", title: "Governors general", file: "src/data/wikidata/governors-general.json", meta: meta(ggData) },
  { id: "chief-justices", title: "Chief justices", file: "src/data/wikidata/chief-justices.json", meta: meta(cjData) },
  { id: "provinces", title: "Provinces and territories", file: "src/data/wikidata/provinces.json", meta: meta(provinceData) },
  { id: "population-history", title: "Census populations", file: "src/data/wikidata/population-history.json", meta: meta(censusData) },
  { id: "population", title: "Population by province", file: "src/data/statcan/population.json", meta: meta(populationData) },
  { id: "immigration", title: "Immigration", file: "src/data/statcan/immigration.json", meta: meta(immigrationData) },
  { id: "age", title: "Age of the population", file: "src/data/statcan/age.json", meta: meta(ageData) },
  { id: "flags", title: "Flags", file: "src/data/flags.json", meta: meta(flagData) },
];

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

export const provinceBySlug = (slug: string) => provinces.find((p) => p.slug === slug);
export const flagBySlug = (slug: string) => flags.find((f) => f.slug === slug);

/** The colour family for a PM term: the family of its first listed party. */
export function partyFamily(term: PrimeMinisterTerm): PartyFamily {
  const fam = familyByName.get(term.parties[0] ?? "");
  if (!fam) throw new Error(`No colour family for party "${term.parties[0]}"`);
  return fam;
}

/** Today in YYYY-MM-DD, used as the end of terms still running. Fixed per build. */
export const buildDate = new Date().toLocaleDateString("en-CA", { timeZone: "America/Toronto" });

const DAY = 86_400_000;
const toTime = (iso: string) => Date.parse(`${iso}T00:00:00Z`);

/** Days in office for one term (an open term runs to the build date). */
export const termDays = (t: Term) => Math.round((toTime(t.end ?? buildDate) - toTime(t.start)) / DAY);
export const totalDays = (terms: Term[]) => terms.reduce((n, t) => n + termDays(t), 0);
export const inOffice = (h: { terms: Term[] }) => h.terms.some((t) => t.end === null);

/** "8 years, 7 months", "3 months", "69 days". */
export function formatDuration(days: number): string {
  if (days < 92) return `${days} day${days === 1 ? "" : "s"}`;
  const months = Math.floor(days / 30.4375);
  const y = Math.floor(months / 12);
  const m = months % 12;
  const parts = [];
  if (y) parts.push(`${y} year${y === 1 ? "" : "s"}`);
  if (m) parts.push(`${m} month${m === 1 ? "" : "s"}`);
  return parts.join(", ");
}

const MONTHS = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];
// Canadian Press abbreviations.
const MON = ["Jan.", "Feb.", "March", "April", "May", "June", "July", "Aug.", "Sept.", "Oct.", "Nov.", "Dec."];

/** "September 25, 1926" (long) or "Sept. 25, 1926" (short, Canadian Press style). */
export function formatDate(iso: string, style: "long" | "short" = "long"): string {
  const [y, m, d] = iso.split("-").map(Number) as [number, number, number];
  const month = (style === "long" ? MONTHS : MON)[m - 1];
  return `${month} ${d}, ${y}`;
}

/** Fractional year for placing a date on a time axis. */
export function yearFraction(iso: string): number {
  const [y] = iso.split("-").map(Number) as [number];
  const start = Date.UTC(y, 0, 1);
  const end = Date.UTC(y + 1, 0, 1);
  return y + (toTime(iso) - start) / (end - start);
}

/** 41798407 → "41,798,407". */
export const formatNumber = (n: number) => n.toLocaleString("en-CA");

/** 41798407 → "41.8 million", 774000 → "774,000". */
export function formatPeople(n: number): string {
  if (n >= 1_000_000) return `${(n / 1_000_000).toFixed(n >= 10_000_000 ? 1 : 2).replace(/\.?0+$/, "")} million`;
  return formatNumber(Math.round(n / 1000) * 1000);
}
